pub const BUILD_COMMIT: &str = env!("REVA_BUILD_COMMIT");
pub const BUILD_TIMESTAMP: &str = env!("REVA_BUILD_TIMESTAMP");

/// The report's lines, without line ends.
pub fn lines() -> Vec<String> {
    vec![
        format!("{NAME} {VERSION}"),
